const OPERATIONS = ['add', 'subtract', 'multiply', 'divide'];

function isNumber(value) {
  return typeof value === 'number' && Number.isFinite(value);
}

export async function listTools() {
  return [
    {
      name: 'calculate',
      description: 'Perform a safe arithmetic calculation on two numbers.',
      inputSchema: {
        type: 'object',
        properties: {
          a: { type: 'number', description: 'The first operand.' },
          b: { type: 'number', description: 'The second operand.' },
          operation: {
            type: 'string',
            enum: OPERATIONS,
            description: 'The arithmetic operation to perform.',
          },
        },
        required: ['a', 'b', 'operation'],
        additionalProperties: false,
      },
    },
  ];
}

export async function callTool(name, args) {
  if (name !== 'calculate') {
    throw new Error(`Unknown tool: ${name}`);
  }

  if (args === null || typeof args !== 'object' || Array.isArray(args)) {
    throw new Error('Arguments must be an object');
  }

  const keys = Object.keys(args);
  const known = new Set(['a', 'b', 'operation']);
  for (const key of keys) {
    if (!known.has(key)) {
      throw new Error(`Unexpected field: ${key}`);
    }
  }

  if (!('a' in args)) throw new Error('Missing required field: a');
  if (!('b' in args)) throw new Error('Missing required field: b');
  if (!('operation' in args)) throw new Error('Missing required field: operation');

  const { a, b, operation } = args;

  if (!isNumber(a)) throw new Error('Field "a" must be a finite number');
  if (!isNumber(b)) throw new Error('Field "b" must be a finite number');
  if (typeof operation !== 'string' || !OPERATIONS.includes(operation)) {
    throw new Error('Unsupported operation');
  }

  let result;
  switch (operation) {
    case 'add':
      result = a + b;
      break;
    case 'subtract':
      result = a - b;
      break;
    case 'multiply':
      result = a * b;
      break;
    case 'divide':
      if (b === 0) throw new Error('Division by zero');
      result = a / b;
      break;
    default:
      throw new Error('Unsupported operation');
  }

  return {
    content: [{ type: 'text', text: String(result) }],
  };
}

